import{_ as e,c as n,a as p,o as i}from"./app-Dm3Xj-PW.js";const c={};function r(d,a){return i(),n("div",null,a[0]||(a[0]=[p('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-11-23-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-11-23-资讯日报"><span>2026-11-23 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="openai公布内部训练数据警惕失控风险" tabindex="-1"><a class="header-anchor" href="#openai公布内部训练数据警惕失控风险"><span>OpenAI公布内部训练数据警惕失控风险</span></a></h3><p>OpenAI 首席科学家首次公开内部对数困惑度数据，指出困惑度若跌入 0.68 至 0.7 区间现有安全对齐将彻底失效，呼吁全球团队联合设立能力红线。</p><p>演进规律：GPT-3.5为0.99，降至0.76能解数学界未解题</p><p>突破预测：AI参与自身研发最快于2027年出现底层技术雪崩</p><p>行业难点：各家测试集不同且思维链推理不直接降低困惑度<a href="https://mp.weixin.qq.com/s?__biz=Mzg3MTkxMjYzOA==&amp;chksm=cfe586b69a47321768c4440a0536448734caf60d064da971d5052d4d1f6324de14a431c776f4&amp;idx=1&amp;mid=2247520413&amp;sn=54f09a3ecbdbc4fcedba71594b101c98" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="owasp推出acs-为agent建立安全控制" tabindex="-1"><a class="header-anchor" href="#owasp推出acs-为agent建立安全控制"><span>OWASP推出ACS，为Agent建立安全控制</span></a></h3><p>网络安全组织 OWASP 推出 Agent 控制标准 ACS，旨在将安全控制与 Agent 执行分离，通过统一协议在工具调用等关键节点实时拦截越权操作。</p><p>双层决策：规则引擎优先，大模型语义判断仅作辅助</p><p>三大支柱：包含实时拦截、事件追踪和组件清单管理</p><p>分级落地：以基础协议为核心，支持数据血缘等可选模块<a href="https://mp.weixin.qq.com/s?__biz=MzAxNjA0MjIzNg==&amp;chksm=82dd38cd9bc9d6f267c143b98bdbb5e3e9ff7a32bd2f3fd81fe76f8362324c40366786984200&amp;idx=1&amp;mid=2650017451&amp;sn=b2c75e8589b3a32110645e71d041625b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="博主卡兹克公开三模型协同工作流配置" tabindex="-1"><a class="header-anchor" href="#博主卡兹克公开三模型协同工作流配置"><span>博主卡兹克公开三模型协同工作流配置</span></a></h3><p>博主卡兹克分享了以 Claude 为中枢调度多模型的工作流：Claude 统筹拆解与前端，Gemini 提供创意与文案，GPT 专攻后端和代码审查。</p><p>Claude负责验收统筹，Gemini当军师，GPT啃硬活</p><p>上线前用GPT把关，历史问题直接写成测试硬拦截<a href="https://mp.weixin.qq.com/s?__biz=MzIyMzA5NjEyMA==&amp;chksm=f1c85f4dcb0d42aeca707011e9159526b7f24224b34636c057902e0dd8a178c7483919a8ac04&amp;idx=1&amp;mid=2647688652&amp;sn=1c25da651ea5f1d34782ace0e20744e8" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="inkling-2-mini发布循环架构模型" tabindex="-1"><a class="header-anchor" href="#inkling-2-mini发布循环架构模型"><span>Inkling 2 Mini发布循环架构模型</span></a></h3><p>Thinking Machines 推出 26.4B 参数的循环架构模型 Inkling 2 Mini，让中间 12 层共享权重执行 3 遍，用推理算力换取串行深度，最高支持 1M 上下文。</p><p>参数激活：单次激活3.4B，循环后有效激活相当于5.4B</p><p>网络规格：物理24层加MoE，每层128个专家选8个</p><p>权重体积：NVFP4加MXFP8混合精度，模型约20GB<a href="https://mp.weixin.qq.com/s?__biz=MzAxMjc3MjkyMg==&amp;chksm=823b1a0ddd36b290db12b21fa4f90fa403e0e9d118aced417d9a3ea96c83e72a7153fed8d674&amp;idx=1&amp;mid=2648435240&amp;sn=c6a0b69a3312eecabf09be8070699f95" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="中科大推出-biomars-2-0-生物实验系统" tabindex="-1"><a class="header-anchor" href="#中科大推出-biomars-2-0-生物实验系统"><span>中科大推出 BioMARS 2.0 生物实验系统</span></a></h3><p>中科大苏州高研院团队推出 BioMARS 2.0，将多智能体系统连接到真实生物实验。在方案规划测试中，其方案质量评分相对 FlashRAG 提升最高 20.9%。</p><p>三轮内将细胞表型评分从 0.435 升至 0.923</p><p>筛选出美金刚等 3 种候选物，具备潜在保护作用<a href="https://mp.weixin.qq.com/s?__biz=MzI3MjM3ODk0NQ==&amp;chksm=ea7550839aa6b15353b6084bae4efdae75e0d510909b237a2d3bdd593decb7134caad04af495&amp;idx=1&amp;mid=2247514479&amp;sn=bd630473f687e92f7682bc9b1766d0ac" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="langchain-超七成运行由计划调度触发" tabindex="-1"><a class="header-anchor" href="#langchain-超七成运行由计划调度触发"><span>LangChain：超七成运行由计划调度触发</span></a></h3><p>LangChain 披露，Deep Agents 中超过 70% 的运行来自计划调度；系统后台自动调查客户并起草邮件，内部销售每人每月省下约 40 小时。</p><p>执行架构：定时调度与异步子 Agent 让长任务不卡主流程</p><p>长期记忆：从人工修改中提炼偏好分人存储，设定压缩机制</p><p>减少打扰：接入 Jev 模型判断发言时机，避免低价值通知<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTMyOTI4Mw==&amp;chksm=fa986b438da6a01e60991ee5e475087b2d29e79516a3beb16f80fdd2e0c9af219f66de14550f&amp;idx=1&amp;mid=2247784298&amp;sn=79f2cbc98b623f4bc08aac4e1c97640a" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="前小米高管团队推两万多元本地ai工作站" tabindex="-1"><a class="header-anchor" href="#前小米高管团队推两万多元本地ai工作站"><span>前小米高管团队推两万多元本地AI工作站</span></a></h3><p>前小米高管白鹏创办的硅基词元推出桌面级 AI 工作站，售价两万多元起，通过自研调度系统让 16GB 显存显卡也能在本地跑 MiniMax H3 视频模型。</p><p>生成速度：768P 分辨率下生成 5 秒视频不到 8 分钟</p><p>系统配置：Windows 预装 9 个模型且支持局域网共用</p><p>定位场景：主打广告与微短剧批量生成，免除云端抽卡费用<a href="https://mp.weixin.qq.com/s?__biz=MzkyNjU2ODM2NQ==&amp;chksm=c3f5b98d8763ab11ca71297b153af7cc9c9079e8b99379597576cf9e596663082f9bef5777c1&amp;idx=2&amp;mid=2247635732&amp;sn=5104c6114d91fa3b54f28bbb7317c5d1" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="深向正向造自动驾驶重卡-tco降22-8" tabindex="-1"><a class="header-anchor" href="#深向正向造自动驾驶重卡-tco降22-8"><span>深向正向造自动驾驶重卡，TCO降22.8%</span></a></h3><p>自动驾驶卡车公司深向阐述其正向造车方案，从底盘与三电原生适配智驾系统。据其披露，相比传统燃油重卡，正向设计可使整车总拥有成本降低22.8%。</p><p>动力域控制器减重40%降本30%，动能回收功率提升20%</p><p>多域融合架构支持数据回传，全车线控底盘保障执行精度<a href="https://mp.weixin.qq.com/s?__biz=MzUyODY1NDE1NA==&amp;chksm=fb290f44c7440311a266f5f547b0f4d34951b7e8542725d0c353065d84dcc75857ea167166b3&amp;idx=1&amp;mid=2247579135&amp;sn=893f8712983d7eafbb033bc9dbc85749" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="中国大模型算力正从出海租卡转攻国产" tabindex="-1"><a class="header-anchor" href="#中国大模型算力正从出海租卡转攻国产"><span>中国大模型算力正从出海租卡转攻国产</span></a></h3><p>文章以未来视角推演中国AI算力演变：受外部限制收紧与海量日常推理挤占，大模型正从出海租卡转向攻坚国产算力，面临精度对齐与系统适配等工程难关。</p><p>出海寻卡：此前阿里字节等在东南亚及北欧租卡训前沿模型</p><p>推理挤占：海量国民级调用大幅挤占了旗舰模型的预训练算力</p><p>硬件适配：昇腾等国产芯片需跨越显存带宽与算子效率差距<a href="https://mp.weixin.qq.com/s?__biz=MzkyNjU2ODM2NQ==&amp;chksm=c3a1cc242681df68ea24ac524a945333c5fa9c7943197843636b2a93325904bb40671bcb6d59&amp;idx=2&amp;mid=2247635689&amp;sn=a0707d62ad6f807cc75011e586241af5" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="编程agent约76-账单花在kv缓存读取" tabindex="-1"><a class="header-anchor" href="#编程agent约76-账单花在kv缓存读取"><span>编程Agent约76%账单花在KV缓存读取</span></a></h3><p>开发者发现每年 200 美元 Claude 订阅能跑出 10 万美元 API 用量，核心在于编程 Agent 超过 90% 的 Token 都在重读历史，读 KV 缓存对厂商近乎零成本。</p><p>成本结构：实际生成仅占9%到18%，76%账单花在缓存读取</p><p>架构避坑：切换便宜模型无法共享缓存，单步成本反暴涨近3倍<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0f4ba37da4e91471fdbff4afe087f79078f78874227172b1886f9f5899f6df79c30339b532c&amp;idx=2&amp;mid=2652744575&amp;sn=b75f90f8b28a74c124a393514f08e8bd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="哈佛等开源虚拟细胞模型strand" tabindex="-1"><a class="header-anchor" href="#哈佛等开源虚拟细胞模型strand"><span>哈佛等开源虚拟细胞模型STRAND</span></a></h3><p>哈佛医学院等开源虚拟细胞模型 STRAND，打破以往只能按基因名预测的限制，改用DNA序列加具体坐标预演干预，可预测非编码区对全细胞基因表达的连锁响应。</p><p>覆盖约95%基因组，可区分同一基因的不同启动入口</p><p>K562扰动判别分数提升32%，跨细胞系吻合率达58.7%<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e902449dbb8d8d2e28c4dcf51243d40ad8508cb69cf2d67f64c799a177186cd38f6a0526fa35&amp;idx=2&amp;mid=2247947754&amp;sn=2d7394fd2ad6b2021392b4883d8e6077" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="ai短剧工作流toonflow获2-2万star" tabindex="-1"><a class="header-anchor" href="#ai短剧工作流toonflow获2-2万star"><span>AI短剧工作流Toonflow获2.2万Star</span></a></h3><p>开源 AI 短剧创作工具 Toonflow 在 GitHub 获得约 2.2 万 Star。它用无限画布把剧本、角色和分镜整合在同一界面，支持接入第三方 API 或本地 ComfyUI。</p><p>客户端支持：提供桌面多系统、安卓端及 Docker 部署</p><p>安全提醒：页面与 API 暂无独立登录鉴权<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MjcxOTM2Nw==&amp;chksm=c27c434ab92596032b4eede84d18f6190612fe18ab76b87f29c5b089dcf999363f156f2a00fe&amp;idx=1&amp;mid=2247504882&amp;sn=a96ad5f5c1f0f044103f6fa98afe0f0f" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯开放7700亿参数混元hy4完整权重" tabindex="-1"><a class="header-anchor" href="#腾讯开放7700亿参数混元hy4完整权重"><span>腾讯开放7700亿参数混元Hy4完整权重</span></a></h3><p>腾讯开源混元Hy4多模态大模型权重，主干总参数达7700亿（单Token激活490亿），支持文本、图像和视频理解，可在Hugging Face等平台下载。</p><p>规格：上下文达1,048,576个Token并提供FP8量化版</p><p>能力：支持界面电脑操作并适配Unity等引擎</p><p>许可：年营收超5000万美元等大规模商业需授权<a href="https://mp.weixin.qq.com/s?__biz=Mzg3Mzg5MjY3Nw==&amp;chksm=cf4bad8996ce75034626ddb465d1ddda17861da7f7d6d7ab2c18821d13e70a312c70345a73ac&amp;idx=1&amp;mid=2247527429&amp;sn=026d9dcd433699c0831d2fea8aa47901" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="_5-款开源新工具-英伟达显卡算力可翻倍" tabindex="-1"><a class="header-anchor" href="#_5-款开源新工具-英伟达显卡算力可翻倍"><span>5 款开源新工具：英伟达显卡算力可翻倍</span></a></h3><p>本周 5 款开源工具发布，其中 Linux 模块 gpu-unlock 可在开机时解除英伟达显卡限速，矩阵算力最高提速 100%；其余涵盖手机操控与代码防逆向等领域。</p><p>mobile-mcp：读取系统无障碍树操控手机</p><p>anatomy：将抽象技术概念生成为可交互的立体机械拆解图</p><p>bla：通过注入假线索与撑爆分析上限，防御 AI 逆向工具<a href="https://mp.weixin.qq.com/s?__biz=MzkwNzU4NTMyMA==&amp;chksm=c11f10454352ac11cc19e89e6ae661f84dde0eb72ed48726bc85c65d5e08668652628c582590&amp;idx=1&amp;mid=2247509965&amp;sn=d916c2b8dc0d0cdb1cb7716aeb965e02" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="清华等测机器人-边想边做成功率仅12" tabindex="-1"><a class="header-anchor" href="#清华等测机器人-边想边做成功率仅12"><span>清华等测机器人：边想边做成功率仅12%</span></a></h3><p>清华大学发布评测基准 Mind2Act World。表现最好的大模型 Agent 在需要边推理边操作的任务上成功率仅有 12%，端到端最高仅 3.6%。</p><p>Agent强在记忆推理，端到端模型缺乏状态记忆</p><p>Agent单回合调用费达25美元，端到端仅需毫秒级</p><p>基准与评测代码已开源，可自动分析失败原因<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85a17e5c3b420659cc57e6beb3172370da3db27aa2cf106c4060b889e6d2b43aa1b430a127dc&amp;idx=1&amp;mid=2651075704&amp;sn=dd36e17788a25d918f6fbc5c3c0907cb" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="uiuc等-11个agent记忆系统大多跑输rag" tabindex="-1"><a class="header-anchor" href="#uiuc等-11个agent记忆系统大多跑输rag"><span>UIUC等：11个Agent记忆系统大多跑输RAG</span></a></h3><p>UIUC与清华等团队测试11个开源Agent记忆系统发现，因加工失真产生「记忆税」，多数系统端到端准确率反而跑输单轮朴素RAG，建库还多耗上亿Token。</p><p>成因：抽取时丢失细节、检索碎片化及跨模型鲁棒性差</p><p>成本：部分系统建库耗时超百小时，收益难抵额外损耗</p><p>解法：并列检索原始记录、回写检索路径或预判未来需求<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0c9a46c2f001b6f3727ec61e077f2a91a032e374f63b496b85d51c0239a83532291087ef8ed&amp;idx=3&amp;mid=2652744575&amp;sn=30dd0cb196f30092f2c09b3c8552c0f5" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="minimax破解密码难题-最高提速4万倍" tabindex="-1"><a class="header-anchor" href="#minimax破解密码难题-最高提速4万倍"><span>MiniMax破解密码难题，最高提速4万倍</span></a></h3><p>MiniMax 发布内部模型密码分析成果，攻破多项后量子密码挑战。在 TII McEliece 挑战中，其单台服务器求解速度比 Anthropic 快最高 43400 倍。</p><p>格同构难题：单核 CPU 跑 30 分钟解出私钥，效率折算提升 690 倍</p><p>算法首杀：0.045 秒生成 Waterfall-256 首个碰撞实例</p><p>安全现状：现行的主流密码标准 AES、RSA 与 SHA-256 仍安全<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f01576398b7f2968f1bd16760c5f53df257c0eb577a9b8bd30cb9e16185641c37cd4fdb3e6b8&amp;idx=1&amp;mid=2652744575&amp;sn=9c64fe2395b7111545ac8b42cd6dbca8" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="五款决策模型评测-jev准确率超95" tabindex="-1"><a class="header-anchor" href="#五款决策模型评测-jev准确率超95"><span>五款决策模型评测：JEV准确率超95%</span></a></h3><p>评测显示，海外决策模型 JEV 整体准确率超 95%，与通用模型 DeepSeek 持平；阿里决策模型为 81.3%，1B 以内开源小模型尚不建议直接商用。</p><p>响应延迟：云端决策模型响应快于通用大模型</p><p>规则敏感：去除选项说明后两款小模型准确率骤降</p><p>开源项目：测试工具与用例已在GitHub开源<a href="https://mp.weixin.qq.com/s?__biz=Mzk1NzQ1ODk5NQ==&amp;chksm=c2bc64ff838e62201061234c96840873fc1fb8e9475acb34558585f681a59b4a569c59708259&amp;idx=1&amp;mid=2247526930&amp;sn=d9a2fb6991ae142936d4af6424c65cec" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="数学家发文称-claude-证明黎曼猜想无效" tabindex="-1"><a class="header-anchor" href="#数学家发文称-claude-证明黎曼猜想无效"><span>数学家发文称 Claude 证明黎曼猜想无效</span></a></h3><p>数学家尼尔森提交论文指出，此前 Claude 辅助完成的 1700 万行黎曼猜想证明存在漏洞，代码虽通过 Lean 验证，但部分条件被设为恒成立导致证明无效。</p><p>论文进展：论文在约31小时内已连续更新14版</p><p>质疑核心：数学条件被写成无论输入什么都成立<a href="https://mp.weixin.qq.com/s?__biz=MzIyNjM2MzQyNg==&amp;chksm=e9b4bfadcf70516376516b53d83d46f5621cf7b49e9d4d0cf76dfee8aa16885ed533cb503210&amp;idx=1&amp;mid=2247730431&amp;sn=85cde3e91a394e395d164f169a1092f6" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',97)]))}const l=e(c,[["render",r]]),s=JSON.parse('{"path":"/posts/2026-11-23.html","title":"AI日报：OpenAI公布内部训练数据警惕失控风险; OWASP推出ACS，为Agent建立安全控制; 博主卡兹克公开三模型协同工作流配置","lang":"zh-CN","frontmatter":{"date":"2026-11-23T00:00:00.000Z","title":"AI日报：OpenAI公布内部训练数据警惕失控风险; OWASP推出ACS，为Agent建立安全控制; 博主卡兹克公开三模型协同工作流配置"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"OpenAI公布内部训练数据警惕失控风险","slug":"openai公布内部训练数据警惕失控风险","link":"#openai公布内部训练数据警惕失控风险","children":[]},{"level":3,"title":"OWASP推出ACS，为Agent建立安全控制","slug":"owasp推出acs-为agent建立安全控制","link":"#owasp推出acs-为agent建立安全控制","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"博主卡兹克公开三模型协同工作流配置","slug":"博主卡兹克公开三模型协同工作流配置","link":"#博主卡兹克公开三模型协同工作流配置","children":[]},{"level":3,"title":"Inkling 2 Mini发布循环架构模型","slug":"inkling-2-mini发布循环架构模型","link":"#inkling-2-mini发布循环架构模型","children":[]},{"level":3,"title":"中科大推出 BioMARS 2.0 生物实验系统","slug":"中科大推出-biomars-2-0-生物实验系统","link":"#中科大推出-biomars-2-0-生物实验系统","children":[]},{"level":3,"title":"LangChain：超七成运行由计划调度触发","slug":"langchain-超七成运行由计划调度触发","link":"#langchain-超七成运行由计划调度触发","children":[]},{"level":3,"title":"前小米高管团队推两万多元本地AI工作站","slug":"前小米高管团队推两万多元本地ai工作站","link":"#前小米高管团队推两万多元本地ai工作站","children":[]},{"level":3,"title":"深向正向造自动驾驶重卡，TCO降22.8%","slug":"深向正向造自动驾驶重卡-tco降22-8","link":"#深向正向造自动驾驶重卡-tco降22-8","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"中国大模型算力正从出海租卡转攻国产","slug":"中国大模型算力正从出海租卡转攻国产","link":"#中国大模型算力正从出海租卡转攻国产","children":[]},{"level":3,"title":"编程Agent约76%账单花在KV缓存读取","slug":"编程agent约76-账单花在kv缓存读取","link":"#编程agent约76-账单花在kv缓存读取","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"哈佛等开源虚拟细胞模型STRAND","slug":"哈佛等开源虚拟细胞模型strand","link":"#哈佛等开源虚拟细胞模型strand","children":[]},{"level":3,"title":"AI短剧工作流Toonflow获2.2万Star","slug":"ai短剧工作流toonflow获2-2万star","link":"#ai短剧工作流toonflow获2-2万star","children":[]},{"level":3,"title":"腾讯开放7700亿参数混元Hy4完整权重","slug":"腾讯开放7700亿参数混元hy4完整权重","link":"#腾讯开放7700亿参数混元hy4完整权重","children":[]},{"level":3,"title":"5 款开源新工具：英伟达显卡算力可翻倍","slug":"_5-款开源新工具-英伟达显卡算力可翻倍","link":"#_5-款开源新工具-英伟达显卡算力可翻倍","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"清华等测机器人：边想边做成功率仅12%","slug":"清华等测机器人-边想边做成功率仅12","link":"#清华等测机器人-边想边做成功率仅12","children":[]},{"level":3,"title":"UIUC等：11个Agent记忆系统大多跑输RAG","slug":"uiuc等-11个agent记忆系统大多跑输rag","link":"#uiuc等-11个agent记忆系统大多跑输rag","children":[]},{"level":3,"title":"MiniMax破解密码难题，最高提速4万倍","slug":"minimax破解密码难题-最高提速4万倍","link":"#minimax破解密码难题-最高提速4万倍","children":[]},{"level":3,"title":"五款决策模型评测：JEV准确率超95%","slug":"五款决策模型评测-jev准确率超95","link":"#五款决策模型评测-jev准确率超95","children":[]},{"level":3,"title":"数学家发文称 Claude 证明黎曼猜想无效","slug":"数学家发文称-claude-证明黎曼猜想无效","link":"#数学家发文称-claude-证明黎曼猜想无效","children":[]}]}],"git":{"updatedTime":1795442389000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"a14f022b785b1eaa8df8b86d07f0630f524557aa","time":1795442389000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-11-23T13:59:49.564Z"}]},"filePathRelative":"posts/2026-11-23.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-11-23 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>OpenAI公布内部训练数据警惕失控风险</h3>\\n<p>OpenAI 首席科学家首次公开内部对数困惑度数据，指出困惑度若跌入 0.68 至 0.7 区间现有安全对齐将彻底失效，呼吁全球团队联合设立能力红线。</p>"}');export{l as comp,s as data};
